\title{The Asymmetric CRT Split of $a^{N-1} \bmod N$ Is Factor-Blind:\\
An Exact Collapse Theorem}
\author{Aristotle}
\date{August 12, 2026}

\begin{document}
\maketitle

\begin{abstract}
For a semiprime $N = pq$ with distinct primes $p, q$, the quantity
$Q(a) = a^{N-1} \bmod N$ is computable in $O(\log N)$ modular multiplications
from $N$ alone. We show that $Q$ possesses a genuinely \emph{asymmetric}
Chinese-Remainder description --- $Q(a) \equiv a^{q-1} \pmod p$ and
$Q(a) \equiv a^{p-1} \pmod q$, so that each coordinate is governed by the
\emph{other} prime's Fermat exponent --- and we then prove, in four independent
ways, that this asymmetry carries no exploitable information about the
factorisation. First, any procedure that isolates one CRT coordinate of $Q$ as a
residue vanishing in the other coordinate yields a prime factor of $N$ by a
single gcd evaluated at the base $a = 1$: reading a coordinate \emph{is}
factoring. Second, every multiplicative consequence of $Q$ factors through the
single invariant $g = \gcd(p-1,q-1)$: we prove $u^{N-1} = 1 \iff u^{g} = 1$ for
all units $u$, that the Fermat liars number exactly $g^2$ and form a group
isomorphic to $(\Zmod{g})^2$, that the image of the $(N-1)$-power endomorphism
has size $\varphi(N)/g^2$, and that this endomorphism is bijective iff $g = 1$.
Third, the gcd variant $\gcd(a^{N-1}-1,N)$ returns a proper factor for exactly
$g(q-1)+g(p-1)-2g^2$ of the $\varphi(N)$ admissible bases, a density
$\approx g/p + g/q$. Fourth, we exhibit Euler's totient as a hint of the same
apparent cost that is \emph{not} factor-blind, delimiting the boundary. An
experiment over eighty near-equal-factor semiprimes near $10^7$ found all
correlations of $Q$ with $p$, $q$, $p+q$, $|p-q|$ inside a $300$-shuffle
permutation null; the theory explains exactly why.
\end{abstract}

\noindent\textbf{Keywords:} integer factorisation, Chinese Remainder Theorem,
Fermat's little theorem, Euler gap, Fermat liars, RSA, idempotents, Rabin split.

\section{Introduction}

\subsection{The search for a cheap factor-dependent quantity}

The security of RSA rests on the presumed hardness of recovering $p$ and $q$
from $N = pq$. Any classical attack must, at some stage, compute a quantity from
$N$ that depends on $p$ and $q$ separately in a way that can be read out. Call a
function $F$ of $N$ (and possibly of auxiliary public inputs such as a base $a$)
a \emph{hint} if it is computable in $\mathrm{poly}(\log N)$ time without the
factorisation, and say the hint \emph{carries signal} if the factorisation can
be recovered in randomised polynomial time from $(N,F)$.

Euler's totient is a hint that carries signal (Section~\ref{sec:totient}). Most
cheap arithmetic quantities are hints that do not. The interest of the present
work is a candidate whose \emph{internal structure} is unusually promising, and
the sharp identification of the reason it nevertheless fails.

\subsection{The candidate}

Fix a semiprime $N = pq$ with $p \ne q$ prime, and set
\[
  Q(a) \;=\; a^{\,N-1} \bmod N .
\]
This is the quantity computed by the Fermat primality test. It is defined from
$N$ alone; it costs $O(\log N)$ modular multiplications by binary exponentiation
(Section~\ref{sec:cost}); it requires no aggregation over many bases; and no
knowledge of $p$ or $q$ enters its computation.

The exponent $N-1 = pq-1$ is symmetric in $p$ and $q$. Yet the identity
\begin{equation}\label{eq:split}
  pq - 1 \;=\; (p-1)q + (q-1)
\end{equation}
is \emph{not} symmetric, and reading it both ways produces the asymmetric CRT
description that motivates everything below.

\section{The asymmetric CRT split}

\subsection{Setting and notation}

Throughout, $p$ and $q$ denote distinct primes, $N = pq$, and $\varphi$ is
Euler's totient, so $\varphi(N) = (p-1)(q-1)$. We write $(\Zmod{N})^\times$ for
the unit group, $\ord_p(a)$ for the multiplicative order of $a$ modulo $p$, and
\[
  Q(a) := a^{\,N-1} \bmod N \in \{0,1,\dots,N-1\}.
\]

\begin{definition}[Euler gap]
The \emph{Euler gap} of $N = pq$ is $g := \gcd(p-1,\,q-1)$.
\end{definition}

We freely use the Chinese Remainder Theorem: since $\gcd(p,q)=1$, reduction
induces $\Zmod{N} \cong \Zmod{p} \times \Zmod{q}$, restricting to a group
isomorphism $(\Zmod{N})^\times \cong (\Zmod{p})^\times \times (\Zmod{q})^\times$.
We call the two components of an element its \emph{left} ($\bmod\ p$) and
\emph{right} ($\bmod\ q$) \emph{CRT coordinates}.

\subsection{The exponent identity}

\begin{lemma}[Asymmetric exponent split]\label{lem:exp}
For positive integers $p,q$ we have $pq - 1 = (p-1)q + (q-1)$.
\end{lemma}

\begin{proof}
$(p-1)q = pq - q$, and $q \le pq$, so the right-hand side equals
$pq - q + q - 1 = pq-1$.
\end{proof}

The point is the \emph{orientation}. Exchanging $p$ and $q$ gives the equally
valid $pq - 1 = (q-1)p + (p-1)$: the same symmetric number admits two
inequivalent decompositions, each adapted to reduction modulo a different prime.

\subsection{The split}

\begin{lemma}[Fermat]\label{lem:fermat}
If $p$ is prime and $\gcd(a,p)=1$ then $a^{p-1} \equiv 1 \pmod p$.
\end{lemma}

\begin{theorem}[Asymmetric CRT split]\label{thm:split}
Let $p$ be prime, $q \ge 1$, and $\gcd(a,p)=1$. Then
$a^{\,pq-1} \equiv a^{\,q-1} \pmod p$. Symmetrically, if $q$ is prime, $p \ge 1$
and $\gcd(a,q)=1$, then $a^{\,pq-1} \equiv a^{\,p-1} \pmod q$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:exp},
\[
  a^{pq-1} = a^{(p-1)q + (q-1)} = \bigl(a^{p-1}\bigr)^{q}\, a^{q-1}
  \equiv 1^{q} \cdot a^{q-1} = a^{q-1} \pmod p,
\]
using Lemma~\ref{lem:fermat}. The second statement is the first with $p$ and $q$
interchanged.
\end{proof}

\begin{corollary}\label{cor:split}
For $N = pq$ with $p,q$ distinct primes and $\gcd(a,N)=1$,
\[
  Q(a) \bmod p = a^{\,q-1} \bmod p, \qquad Q(a) \bmod q = a^{\,p-1} \bmod q.
\]
\end{corollary}

\begin{proof}
Since $p \mid N$, reducing $Q(a)$ further modulo $p$ gives $a^{N-1} \bmod p$;
apply Theorem~\ref{thm:split}. Likewise for $q$.
\end{proof}

Corollary~\ref{cor:split} is the structural content: the left CRT coordinate of
$Q$ is controlled by $q$, the right by $p$. Each coordinate ``knows'' the prime
it is not reduced against.

\subsection{Exactness}

\begin{theorem}[CRT exactness]\label{thm:unique}
Let $p \ne q$ be primes, $\gcd(a,pq)=1$, and let $x < pq$ satisfy
$x \equiv a^{\,q-1} \pmod p$ and $x \equiv a^{\,p-1} \pmod q$. Then $x = Q(a)$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:split}, $x \equiv a^{pq-1}$ modulo $p$ and modulo $q$. Since
$\gcd(p,q)=1$ these combine to $x \equiv a^{pq-1} \pmod{pq}$, and $0 \le x < pq$
forces $x = a^{pq-1} \bmod pq = Q(a)$.
\end{proof}

\subsection{The exponent gcd collapse}

\begin{theorem}[Exponent gcd collapse]\label{thm:gcdcollapse}
For positive $p,q$,
\[
  \gcd(pq-1,\,p-1) = \gcd(q-1,\,p-1), \qquad
  \gcd(pq-1,\,q-1) = \gcd(p-1,\,q-1),
\]
so both equal the Euler gap $g$; in particular
$\gcd(N-1,p-1) = \gcd(N-1,q-1)$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:exp}, $pq-1 = (q-1) + (p-1)q$, and $\gcd(m + kn, n) =
\gcd(m,n)$ with $m = q-1$, $k=q$, $n=p-1$. Exchange $p$ and $q$ for the second
identity; the right-hand sides agree by symmetry of the gcd.
\end{proof}

Although $N-1$ \emph{reduces} to $q-1$ modulo $p$ and to $p-1$ modulo $q$, the
divisibility content it retains against either prime is the same number $g$.

\section{Barrier: reading a CRT coordinate is factoring}

\subsection{A gcd extraction lemma}

\begin{lemma}\label{lem:gcdext}
Let $r$ be prime, $d \mid m$ and $r \nmid m$. Then $\gcd(m, dr) = d$.
\end{lemma}

\begin{proof}
Since $r$ is prime and $r \nmid m$, $\gcd(r,m)=1$, so $r$ may be cancelled:
$\gcd(m, rd) = \gcd(m,d) = d$ because $d \mid m$.
\end{proof}

\subsection{The idempotent is the factorisation}

\begin{definition}
An integer $e$ is a \emph{CRT idempotent} for $(p,q)$ if $e \equiv 1 \pmod p$
and $e \equiv 0 \pmod q$. Its image in $\Zmod{N}$ satisfies $e^2 = e$.
\end{definition}

\begin{theorem}[Idempotent $\Rightarrow$ factor]\label{thm:idem}
If $p$ is prime, $e \equiv 1 \pmod p$ and $e \equiv 0 \pmod q$, then
$\gcd(e, pq) = q$.
\end{theorem}

\begin{proof}
$e \equiv 0 \pmod q$ gives $q \mid e$. If $p \mid e$ then $1 \equiv 0 \pmod p$,
i.e.\ $p \mid 1$, contradicting $p>1$. So $p \nmid e$, and
Lemma~\ref{lem:gcdext} with $m = e$, $d = q$, $r = p$ applies.
\end{proof}

\begin{theorem}[Factor $\Rightarrow$ idempotent]\label{thm:existidem}
If $p \ne q$ are primes, there exists $e$ with $e \equiv 1 \pmod p$ and
$e \equiv 0 \pmod q$.
\end{theorem}

\begin{proof}
$\gcd(p,q)=1$, so the Chinese Remainder Theorem solves the two congruences
simultaneously.
\end{proof}

\begin{corollary}[Equivalence]
For $N = pq$ with distinct prime factors, producing a CRT idempotent and
producing the factor $q$ are interchangeable tasks.
\end{corollary}

\subsection{The component-reading barrier}

\begin{definition}
A \emph{component reader} for $Q$ is a function $s : \mathbb{N} \to \mathbb{N}$
with $s(a) \equiv a^{\,q-1} \pmod p$ and $s(a) \equiv 0 \pmod q$ for every $a$.
\end{definition}

The first condition says $s(a)$ reproduces the left CRT coordinate of $Q(a)$
(Corollary~\ref{cor:split}); the second says $s$ has \emph{isolated} that
coordinate.

\begin{theorem}[Component-reading barrier]\label{thm:barrier}
Let $p$ be prime and let $s$ be a component reader. Then
$\gcd\bigl(s(1),\, pq\bigr) = q$: a single evaluation at $a=1$, followed by one
gcd, returns a prime factor of $N$.
\end{theorem}

\begin{proof}
At $a=1$ we get $s(1) \equiv 1^{q-1} = 1 \pmod p$ and $s(1) \equiv 0 \pmod q$,
so $s(1)$ is a CRT idempotent; apply Theorem~\ref{thm:idem}.
\end{proof}

\begin{remark}
Theorem~\ref{thm:barrier} is deliberately generous to the adversary: it assumes
nothing about how $s$ is computed, allows $s$ to be an arbitrary oracle, and
needs only one query, at the trivial base. No computational assumption is
involved: coordinate isolation and factorisation are the same object.
\end{remark}

\begin{remark}
The theorem does not assert that no polynomial-time factoring algorithm exists,
nor that no other feature of $Q$ can leak. It asserts that the \emph{specific}
route suggested by the asymmetry --- isolate a coordinate, then exploit it ---
is circular.
\end{remark}

\subsection{The general splitting engine}

\begin{theorem}[Splitting lemma]\label{thm:splitengine}
Let $p \ne q$ be primes, $N = pq$, and let $u,v \in \mathbb{Z}$ satisfy:
(i) $N \mid uv$; (ii) $N \nmid u$ and $N \nmid v$; (iii) no prime of $N$ divides
both $u$ and $v$. Then $\gcd(|u|, N) \in \{p,q\}$.
\end{theorem}

\begin{proof}
From $N \mid uv$ we get $p \mid uv$ and $q \mid uv$, so each of $p,q$ divides
$u$ or $v$. If both divide $u$ then $N \mid u$, contradicting (ii); similarly
for $v$. If $p \mid u$ and $q \mid v$, then $q \nmid u$ by (iii), and
Lemma~\ref{lem:gcdext} gives $\gcd(|u|,pq)=p$. The remaining case is symmetric
and gives $q$.
\end{proof}

\begin{corollary}[Nontrivial idempotents split]\label{cor:idemsplit}
If $N \mid e(e-1)$ while $e \not\equiv 0$ and $e \not\equiv 1 \pmod N$, then
$\gcd(|e|,N)$ is a prime factor of $N$.
\end{corollary}

\begin{proof}
Apply Theorem~\ref{thm:splitengine} with $u = e$, $v = e-1$; a common prime
divisor would divide $(e)-(e-1)=1$.
\end{proof}

\begin{corollary}[Rabin's split]\label{cor:rabin}
Let $p,q$ be distinct odd primes and $x^2 \equiv 1 \pmod N$ with
$x \not\equiv \pm 1 \pmod N$. Then $\gcd(|x-1|,N)$ is a prime factor of $N$.
\end{corollary}

\begin{proof}
Apply Theorem~\ref{thm:splitengine} with $u = x-1$, $v = x+1$, noting
$uv = x^2-1$. A common odd prime divisor would divide $(x+1)-(x-1) = 2$.
\end{proof}

Corollary~\ref{cor:rabin} identifies the exact point at which the Miller--Rabin
test crosses from certifying compositeness to factoring; that discovery, like
coordinate reading, is an oracle for the CRT split.

\section{The Euler-gap collapse}

\begin{lemma}\label{lem:gcdpow}
Let $G$ be a finite group, $x \in G$, and $n,m$ with $\gcd(n,|G|)=\gcd(m,|G|)$.
Then $x^n = 1 \iff x^m = 1$.
\end{lemma}

\begin{proof}
If $x^n=1$ then $\ord(x) \mid n$ and $\ord(x) \mid |G|$, so
$\ord(x) \mid \gcd(n,|G|) = \gcd(m,|G|) \mid m$, whence $x^m=1$. Symmetric
converse.
\end{proof}

\begin{theorem}[Coordinatewise collapse]\label{thm:coordcollapse}
Let $p$ be prime, $q \ge 1$. For every $x \in (\Zmod{p})^\times$,
$x^{\,pq-1} = 1 \iff x^{\,g} = 1$ with $g = \gcd(p-1,q-1)$; symmetrically on the
right.
\end{theorem}

\begin{proof}
$|(\Zmod{p})^\times| = p-1$ and, by Theorem~\ref{thm:gcdcollapse},
$\gcd(pq-1,p-1)=g=\gcd(g,p-1)$ since $g \mid p-1$. Apply
Lemma~\ref{lem:gcdpow}.
\end{proof}

\begin{theorem}[Fermat test $=$ Euler-gap test]\label{thm:fermatgap}
For distinct primes $p,q$, $N=pq$, and every unit $u \in (\Zmod{N})^\times$,
\[
  u^{\,N-1} = 1 \iff u^{\,g} = 1 .
\]
\end{theorem}

\begin{proof}
Under the CRT isomorphism a power identity holds iff it holds in both
coordinates; apply Theorem~\ref{thm:coordcollapse} in each.
\end{proof}

\begin{definition}
A unit $u$ is a \emph{Fermat liar} if $u^{N-1}=1$. The liars form the subgroup
$L = \ker \pi$, where $\pi(u) = u^{N-1}$.
\end{definition}

\begin{lemma}\label{lem:cyccount}
For $r$ prime, the number of $x \in (\Zmod{r})^\times$ with $x^n=1$ is
$\gcd(r-1,n)$.
\end{lemma}

\begin{proof}
$(\Zmod{r})^\times$ is cyclic of order $r-1$, and in a cyclic group of order $m$
the $n$-th power map has kernel of size $\gcd(m,n)$.
\end{proof}

\begin{theorem}[Liar count]\label{thm:liarcount}
$|L| = g^2$.
\end{theorem}

\begin{proof}
Via CRT, $L$ corresponds to pairs $(x,y)$ with $x^{N-1}=1$ and $y^{N-1}=1$, a
product set of sizes $\gcd(p-1,N-1)=g$ and $\gcd(q-1,N-1)=g$ by
Lemma~\ref{lem:cyccount} and Theorem~\ref{thm:gcdcollapse}.
\end{proof}

\begin{theorem}[Liar group structure]\label{thm:liargroup}
$L \cong \Zmod{g} \times \Zmod{g}$.
\end{theorem}

\begin{proof}
CRT carries $L$ onto $K_p \times K_q$, the kernels of the $(N-1)$-power maps in
each coordinate. Each is a subgroup of a cyclic group, hence cyclic, of order
$g$ by the computation in Theorem~\ref{thm:liarcount}.
\end{proof}

\begin{corollary}[Indistinguishability]\label{cor:indist}
If $\gcd(p-1,q-1) = \gcd(p'-1,q'-1)$ then the Fermat-liar groups of $N=pq$ and
$N'=p'q'$ are isomorphic; hence no isomorphism-invariant statistic of the liar
group distinguishes them.
\end{corollary}

\begin{example}
$33 = 3\cdot 11$ has $g = \gcd(2,10)=2$; $35 = 5\cdot 7$ has $g=\gcd(4,6)=2$.
Both liar groups are $\cong \Zmod{2}\times\Zmod{2}$ with exactly $4$ liars,
despite the factorisations sharing no prime.
\end{example}

\begin{theorem}[Gap bound]\label{thm:gapbound}
For distinct primes $p,q$, $\;2g^2 \le (p-1)(q-1) = \varphi(N)$.
\end{theorem}

\begin{proof}
Assume $p<q$. Then $g \mid p-1$ gives $g \le p-1$. Also $g \mid q-1$; if
$g = q-1$ then $q-1 \le p-1$, contradicting $p<q$, so $q-1 = cg$ with $c \ge 2$,
i.e.\ $2g \le q-1$. Multiply: $2g^2 \le (q-1)(p-1)$.
\end{proof}

\begin{corollary}[Liar density at most one half]\label{cor:half}
$2|L| \le \varphi(N)$: a uniformly random base detects the compositeness of a
semiprime with probability at least $1/2$.
\end{corollary}

\begin{corollary}[No semiprime Carmichael numbers]
For distinct primes $p,q$ there is a unit $u$ with $u^{N-1} \ne 1$.
\end{corollary}

\begin{proof}
Otherwise $|L| = \varphi(N) > 0$ and Corollary~\ref{cor:half} gives
$2\varphi(N) \le \varphi(N)$, absurd.
\end{proof}

\begin{theorem}[Image of the power map]\label{thm:image}
$g^2 \cdot |\im \pi| = \varphi(N)$.
\end{theorem}

\begin{proof}
First isomorphism theorem, with $|\ker \pi| = g^2$ by
Theorem~\ref{thm:liarcount}.
\end{proof}

\begin{theorem}[Bijectivity criterion]
The map $u \mapsto u^{N-1}$ on $(\Zmod{N})^\times$ is bijective iff $g=1$.
\end{theorem}

\begin{proof}
An endomorphism of a finite group is bijective iff injective iff its kernel is
trivial, i.e.\ $g^2 = 1$.
\end{proof}

\section{The reveal-density law for the gcd variant}

\begin{theorem}[Arithmetic criterion]\label{thm:criterion}
Let $p,q$ be primes, $a \ge 1$, $N = pq$. If $a^{N-1} \equiv 1 \pmod p$ but
$a^{N-1} \not\equiv 1 \pmod q$, then $\gcd(a^{N-1}-1,N)=p$; symmetrically the
other way round gives $q$. Otherwise the gcd is $1$ or $N$.
\end{theorem}

\begin{proof}
Write $M = a^{N-1}-1 \ge 0$. The hypotheses say $p \mid M$ and $q \nmid M$;
apply Lemma~\ref{lem:gcdext} with $d=p$, $r=q$.
\end{proof}

\begin{theorem}[Order form]\label{thm:orderform}
For $\gcd(a,p)=1$, $\;a^{N-1} \equiv 1 \pmod p$ if and only if
$\ord_p(a) \mid q-1$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:split}, $a^{N-1} \equiv a^{q-1} \pmod p$, and
$a^{q-1} \equiv 1$ iff $\ord_p(a) \mid q-1$.
\end{proof}

Working in $(\Zmod{p})^\times \times (\Zmod{q})^\times$, put
$A = \{(x,y) : x^{N-1}=1\}$ and $B = \{(x,y): y^{N-1}=1\}$.

\begin{lemma}\label{lem:ABcount}
$|A| = g(q-1)$, $|B| = g(p-1)$, and $|A \cap B| = g^2$.
\end{lemma}

\begin{proof}
$A$ constrains only the first coordinate, leaving $\gcd(p-1,N-1)=g$ choices
there and $q-1$ free choices of $y$; symmetrically for $B$. Finally $A\cap B$ is
the liar set, of size $g^2$ (Theorem~\ref{thm:liarcount}).
\end{proof}

\begin{theorem}[Reveal-density law]\label{thm:reveal}
The gcd variant $\gcd(a^{N-1}-1,N)$ returns a proper prime factor of $N$ for
exactly
\[
  R \;=\; g(q-1) + g(p-1) - 2g^2
\]
of the $\varphi(N) = (p-1)(q-1)$ bases coprime to $N$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:criterion} a base reveals a factor exactly when it lies in
$A \triangle B$; use $|A\setminus B| = g(q-1)-g^2$ and
$|B \setminus A| = g(p-1)-g^2$ from Lemma~\ref{lem:ABcount}.
\end{proof}

\begin{corollary}[Density]
\[
  \frac{R}{\varphi(N)} = \frac{g}{p-1} + \frac{g}{q-1}
  - \frac{2g^2}{\varphi(N)} \;\approx\; \frac{g}{p} + \frac{g}{q}.
\]
\end{corollary}

\begin{corollary}[Trivial gap]
If $g=1$ then exactly $R = (p-1)+(q-1)-2$ bases reveal a factor: a probability
of order $1/p + 1/q$, negligible at cryptographic sizes.
\end{corollary}

The gcd variant is therefore useful only when $p-1$ and $q-1$ share a large
common divisor --- a smoothness condition already exploited by Pollard's $p-1$
method and already defended against by strong-prime generation. The asymmetric
split contributes nothing beyond it.

\section{A hint that does carry signal: the totient}\label{sec:totient}

\begin{lemma}\label{lem:sum}
For $p,q \ge 2$ and $N = pq$, $\;N + 1 - \varphi(N) = p + q$.
\end{lemma}

\begin{proof}
$\varphi(N) = pq - p - q + 1$, so $N+1-\varphi(N) = p+q$.
\end{proof}

\begin{lemma}\label{lem:diff}
If $q<p$ then $(p+q)^2 - 4pq = (p-q)^2$.
\end{lemma}

\begin{theorem}[The totient factors $N$]\label{thm:totient}
Let $N = pq$ with $2 \le q < p$ prime and $s = N+1-\varphi(N)$. Then
\[
  p = \frac{s + \sqrt{s^2 - 4N}}{2}, \qquad
  q = \frac{s - \sqrt{s^2 - 4N}}{2}.
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:sum}, $s = p+q$; by Lemma~\ref{lem:diff},
$\sqrt{s^2-4N} = p-q$. Then $(s+(p-q))/2 = p$ and $(s-(p-q))/2 = q$.
\end{proof}

Theorem~\ref{thm:totient} needs no gcd, no randomness and no search. Both
$\varphi(N)$ and $Q(a)$ look like single cheap numbers attached to $N$; one
determines the factorisation outright, the other determines nothing beyond
$(N,g)$. The distinction is not cost but what the quantity is a function of.

\section{Cost}\label{sec:cost}

Define binary exponentiation by $\powMod(m,a,0) = 1 \bmod m$ and, for $n \ge 1$,
$h = \powMod(m,a,\lfloor n/2 \rfloor)$ with output $h^2 \bmod m$ if $n$ is even
and $h^2 (a \bmod m) \bmod m$ if $n$ is odd.

\begin{theorem}[Correctness]
$\powMod(m,a,n) = a^n \bmod m$ for all $m,a,n$.
\end{theorem}

\begin{proof}
Strong induction on $n$. For $n=0$ both sides are $1 \bmod m$. For $n \ge 1$ set
$k = \lfloor n/2 \rfloor$, so $h = a^k \bmod m$ by induction. If $n = 2k$ then
$a^n = a^k a^k$; if $n = 2k+1$ then $a^n = a^k a^k a$. Multiplicativity of
reduction gives the two branches.
\end{proof}

\begin{theorem}[Logarithmic depth]
The recursion depth of $\powMod(m,a,n)$ is at most the binary length of $n$.
\end{theorem}

\begin{proof}
Strong induction. Depth $0$ for $n=0$. For $n \ge 1$ with binary length $\ell$
we have $n < 2^\ell$, so $\lfloor n/2 \rfloor < 2^{\ell-1}$ has binary length at
most $\ell-1$; by induction its depth is at most $\ell-1$, and one more call
gives $\ell$.
\end{proof}

\begin{corollary}
$Q(a) = \powMod(N,a,N-1)$ costs $O(\log N)$ modular multiplications, with no
knowledge of the factorisation and no aggregation over bases.
\end{corollary}

